var drag=null,moved=0;cv.addEventListener('pointerdown',function(e){drag=[e.clientX,e.clientY];moved=0;cv.setPointerCapture(e.pointerId)});
cv.addEventListener('pointermove',function(e){if(!drag)return;var dx=e.clientX-drag[0],dy=e.clientY-drag[1];moved+=Math.abs(dx)+Math.abs(dy);yaw+=dx*.01;if(e.pointerType!='touch')pitch=Math.max(-1.57,Math.min(1.57,pitch+dy*.01));drag=[e.clientX,e.clientY];draw()});
function end(e){if(drag&&moved<6){var r=cv.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top,best=null,bd=28;hits.forEach(function(h){var d=Math.hypot(h.x-x,h.y-y);if(d<bd){bd=d;best=h}});if(best){sel=best.kind=='imu'?{kind:'imu'}:{kind:'cam',i:best.i};info()}}drag=null;draw()}
cv.addEventListener('pointerup',end);cv.addEventListener('pointercancel',function(){drag=null});
cv.addEventListener('wheel',function(e){if(e.ctrlKey){e.preventDefault();zoom=Math.max(.5,Math.min(4,zoom*(e.deltaY<0?1.1:.9)));draw()}},{passive:false});
cv.addEventListener('keydown',function(e){var k=e.key;if(k=='ArrowLeft')yaw-=.1;else if(k=='ArrowRight')yaw+=.1;else if(k=='ArrowUp')pitch=Math.min(1.57,pitch+.1);else if(k=='ArrowDown')pitch=Math.max(-1.57,pitch-.1);else return;e.preventDefault();draw()});
